float rand(vec2 st)
{
    return fract(sin(dot(st, vec2(12.9898, 73.3454))) * 438474.0);
}

float noise_2d(vec2 st)
{
    vec2 i = floor(st);
    vec2 f = fract(st);

    //taking random value from points on a init rect
    float a = rand(i + vec2(0.0, 0.0));
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));

    //Hermite curve interpolation instead of smoothstep because i am a cool kid :)
    vec2 u = f * f * (3.0 - 2.0 * f);
    // u = smoothstep(0.0, 1.0, f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

#define OCTAVES 8
//Fractal Brownian Motion
float fbm(vec2 st)
{
    float value = 0.0;
    float A = 0.5;

    for (int i = 0; i < OCTAVES; i++)
    {
        value += A * noise_2d(st);
        st *= 1.7;
        A *= 0.55;
    }
    return value;
}

float pattern(vec2 p)
{
    vec2 q = vec2(fbm(p + vec2(0.0, 0.0)), fbm(p + vec2(4.54, 8.3)));
    return fbm(p + q * 5.0);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = fragCoord / iResolution.xy;
    st *= 6.0;


    vec3 color;
    vec2 q = vec2(0.);
    q.x = fbm(st + .01 * iTime);
    q.y = fbm(st + vec2(1.0));

    vec2 r = vec2(0.);
    r.x = fbm(st + 1.608 * q + vec2(1.7, 9.2) + 0.15 * iTime);
    r.y = fbm(st + 1.0 * q + vec2(8.3, 2.8) + 0.126 * iTime);

    float f = fbm(st + r);

    color = mix(vec3(0.17, 0.08, 0.067),
            vec3(0.960, 0.856, 0.104),
            clamp((pow(f, 10.0)) * 4.0, 0.0, 1.0));

    color = mix(color,
            vec3(0.885, 0.436, 0.086),
            clamp(length(q), 0.0, 1.0));

    color = mix(color,
            vec3(0.959, 1.000, 0.900),
            clamp(length(r.x), 0.0, 1.0));
    fragColor = vec4((f*f*f+.6*f*f+.5*f)*color, 1.0);
}
